/* Separate stock/sales snapshot; duplicate month headers are read by position. */
(()=>{
 const branches=['MGR1','MGR2','LLG'];let pending=null,run=0,panel=null,anchor=null;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const allowed=()=>['admin','purchasing'].includes(window.PO?.state.data?.me?.role);
 async function rpc(name,args){const c=window.POStockContext;const r=await c.client.rpc(name,{w:c.C.workspaceId,...args});if(r.error)throw Error(r.error.message);return r.data}
 function parse(matrix,products){
  const rows=matrix.filter(r=>r.some(v=>String(v).trim()!==''));if(rows.length<2)throw Error('File kosong');
  const h=rows[0].map(v=>String(v).trim().toLowerCase());if(h.length!==14||h[0]!=='kode'||h[1]!=='nama barang'||h[2]!=='mgr1'||h[6]!=='mgr2'||h[10]!=='llg')throw Error('Urutan kolom harus kode, nama barang, MGR1 dan 3 bulan, MGR2 dan 3 bulan, LLG dan 3 bulan');
  const months=h.slice(3,6).map(v=>Number(/^bulan\s+(\d+)$/.exec(v)?.[1]));if(months.some(m=>!Number.isInteger(m)||m<1||m>12)||new Set(months).size!==3||[7,11].some(i=>h.slice(i,i+3).some((v,j)=>v!==h[j+3])))throw Error('Tiga kolom bulan harus sama pada setiap cabang');
  const items=Object.create(null),known=new Set(products.map(p=>p.id));if(rows.length>10001)throw Error('Maksimal 10.000 barang');
  rows.slice(1).forEach((r,i)=>{const code=String(r[0]??'').trim();if(!known.has(code))throw Error('Baris '+(i+2)+': kode belum terdaftar '+code);if(items[code])throw Error('Kode duplikat: '+code);if(r.length>14&&r.slice(14).some(v=>String(v).trim()))throw Error('Kolom tambahan tidak diizinkan');const item={};branches.forEach((b,j)=>{item[b]=Array.from({length:4},(_,k)=>{const raw=String(r[2+j*4+k]??'').trim();if(!/^\d+([.,]\d+)?$/.test(raw))throw Error('Baris '+(i+2)+': stok dan penjualan wajib angka, isi 0 jika kosong');const n=Number(raw.replace(',','.'));if(!Number.isFinite(n)||n>1e9)throw Error('Jumlah terlalu besar');return n})});items[code]=item});return {months,items};
 }
 function close(){run++;panel?.remove();panel=null;anchor=null}
 function position(){if(!panel||!anchor?.isConnected)return close();const r=anchor.getBoundingClientRect(),v=window.visualViewport,top=v?.offsetTop||0,height=v?.height||innerHeight;const left=Math.max(8,Math.min(r.left,innerWidth-panel.offsetWidth-8));const above=r.top-panel.offsetHeight-8;panel.style.left=left+'px';panel.style.top=Math.max(top+8,Math.min(above>=top+8?above:r.bottom+8,top+height-panel.offsetHeight-8))+'px'}
 function packReference(code){const product=window.PO?.state.data?.products.find(p=>p.id===code),pack=window.POModel?.productPack(product);const idx=pack?.units.indexOf('CRT')??-1;if(idx<0)return '<p class="stock-pack-reference">Konversi CRT belum terdaftar di master produk.</p>';const parts=pack.units.slice(idx+1).map((u,j)=>(pack.factors[idx]/pack.factors[idx+j+1]).toLocaleString('id-ID',{maximumFractionDigits:4})+' '+u);return '<p class="stock-pack-reference"><strong>Isi 1 CRT'+(parts.length?' = '+esc(parts.join(' = ')):' (satuan dasar CRT)')+'</strong></p>';}
 async function show(code,target){close();if(!allowed()||!code)return;anchor=target;const epoch=PO.state.epoch,id=++run;panel=document.createElement('div');panel.className='stock-popover';panel.setAttribute('role','region');panel.setAttribute('aria-label','Stok dan penjualan');panel.innerHTML='<b>'+esc(code)+'</b>'+packReference(code)+'<p role="status">Memuat stok dan penjualan...</p>';document.body.append(panel);position();try{const d=await rpc('po_stock_sales_read',{code});if(id!==run||epoch!==PO.state.epoch)return;panel.innerHTML='<b>'+esc(code)+' &middot; Stok & Penjualan</b>'+packReference(code)+(d?.item?'<table><thead><tr><th>Toko</th><th>Stok</th>'+d.months.map(m=>'<th>Bln '+m+'</th>').join('')+'</tr></thead><tbody>'+branches.map(b=>'<tr><th>'+b+'</th>'+d.item[b].map(n=>'<td>'+Number(n).toLocaleString('id-ID')+'</td>').join('')+'</tr>').join('')+'</tbody></table><small>Sesuai satuan pada data sumber. Diperbarui '+esc(new Date(d.updated_at).toLocaleDateString('id-ID'))+'</small>':'<p>Data barang ini belum diimpor.</p>');position()}catch(e){if(id===run){panel.innerHTML='<b>Stok & Penjualan</b>'+packReference(code)+'<p>'+esc(e.message)+'</p>';position()}}}
 function page(){close();pending=null;if(!allowed())return;document.querySelector('#main').innerHTML='<h1>Stok & Penjualan</h1><section class="panel stock-import"><p>Impor Excel mengganti seluruh data stok dan penjualan sebelumnya. Master produk dan PO tetap tersimpan.</p><p>Kolom: kode, nama barang, mgr1, bulan 8, bulan 9, bulan 10, mgr2, bulan 8, bulan 9, bulan 10, llg, bulan 8, bulan 9, bulan 10. Nomor bulan boleh diganti, urutannya harus sama untuk ketiga cabang. Simpan kode sebagai Teks dan isi angka 0 jika tidak ada stok/penjualan.</p><button class="btn" onclick="StockSales.template()">Unduh Template Excel</button><input aria-label="Impor stok dan penjualan" type="file" accept=".xlsx,.xls,.csv" onchange="StockSales.read(this.files[0])"><div id="stock-review"></div></section>'}
 async function read(file){pending=null;const el=document.querySelector('#stock-review'),epoch=PO.state.epoch;if(!file)return;el.textContent='Memeriksa file...';try{if(file.size>5*1024*1024)throw Error('Maksimal 5 MB');const book=XLSX.read(await file.arrayBuffer(),{type:'array'});const d=parse(XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{header:1,defval:'',raw:false}),PO.state.data.products);if(epoch!==PO.state.epoch||!el.isConnected)return;pending=d;el.innerHTML='<p>'+Object.keys(d.items).length+' barang. Bulan '+d.months.join(', ')+'. Data lama akan diganti.</p><button class="btn primary" onclick="StockSales.save()">Ganti Data Stok & Penjualan</button>'}catch(e){el.textContent=e.message}}
 async function save(){if(!pending||!allowed()||PO.state.busy)return;if(!confirm('Ganti seluruh data stok dan penjualan dengan file ini?'))return;PO.state.busy=true;const el=document.querySelector('#stock-review');try{await rpc('po_stock_sales_replace',{snapshot:pending});pending=null;if(el?.isConnected)el.textContent='Data stok dan penjualan berhasil diganti.'}catch(e){if(el?.isConnected)el.textContent=e.message}finally{PO.state.busy=false}}
 function template(){const head=['kode','nama barang',...branches.flatMap(b=>[b.toLowerCase(),'bulan 8','bulan 9','bulan 10'])],p=PO.state.data.products[0],book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,XLSX.utils.aoa_to_sheet([head,[p?.id||'00123',p?.name||'Nama barang',...Array(12).fill(0)]]),'Stok Penjualan');XLSX.writeFile(book,'template-stok-penjualan.xlsx')}
 document.addEventListener('pointerdown',e=>{if(panel&&!panel.contains(e.target)&&!anchor?.contains(e.target))close()},true);
 document.addEventListener('change',e=>{if(e.target.matches('.item-product'))show(e.target.value,e.target)});
 document.addEventListener('focusin',e=>{if(e.target.matches('.monthly-qty'))show(e.target.closest('tr').cells[1].textContent.trim(),e.target)});
 window.addEventListener('resize',position);window.addEventListener('scroll',position,true);window.visualViewport?.addEventListener('resize',position);
 new MutationObserver(()=>{if(panel&&(!anchor?.isConnected||!allowed()))close()}).observe(document.body,{childList:true,subtree:true});
 window.StockSales={page,read,save,template,show,close,parse};
})();
